                return;
            size = next;
            update();
        });
        if (contentRef.current)
            observer.observe(contentRef.current);
        window.addEventListener("resize", update);
        window.addEventListener("scroll", update, true);
        return () => {
            active = false;
            observer.disconnect();
            window.removeEventListener("resize", update);
            window.removeEventListener("scroll", update, true);
        };
    }, [trigger, treeAnimated]);
    const focusedOnOpen = useRef(false);
    useEffect(() => {
        if (!position || focusedOnOpen.current)
            return;
        const raf = requestAnimationFrame(() => {
            focusedOnOpen.current = true;
            tabRefs.current[filter]?.focus({ preventScroll: true });
        });
        return () => cancelAnimationFrame(raf);
    }, [position, filter]);
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key !== "Escape" || event.defaultPrevented)
                return;
            event.preventDefault();
            onClose(true);
        };
        const onPointerDown = (event: PointerEvent) => {
            const target = event.target as Node | null;
            if (!target)
                return;
            if (floatingRef.current?.contains(target) || wrapper.current?.contains(target))
                return;
            onClose(false);
        };
        document.addEventListener("keydown", onKeyDown);
        document.addEventListener("pointerdown", onPointerDown);
        return () => {
            document.removeEventListener("keydown", onKeyDown);
            document.removeEventListener("pointerdown", onPointerDown);
        };
    }, [onClose, wrapper]);
    useEffect(() => {
        const target = pendingFocus.current;
        if (target === null)
            return;
        pendingFocus.current = null;
        requestAnimationFrame(() => {
            const row = target === "" ? null : floatingRef.current?.querySelector<HTMLElement>(`li[data-notification-row="${target}"]`);
            const el = row ? row.querySelector<HTMLElement>("button") : tabRefs.current[filter];
            el?.focus({ preventScroll: true });
        });
    });
    const remove = (item: NotificationItem, action: (item: NotificationItem) => void) => {
        const index = visible.findIndex((entry) => entry.id === item.id);
        const next = visible[index + 1] ?? visible[index - 1];
        pendingFocus.current = next ? next.id : "";
        action(item);
    };
    const onTabKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
        const index = tabs.findIndex((tab) => tab.id === filter);
        let nextIndex = -1;
        if (event.key === "ArrowRight")
            nextIndex = (index + 1) % tabs.length;
        else if (event.key === "ArrowLeft")
            nextIndex = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "Home")
            nextIndex = 0;
        else if (event.key === "End")
            nextIndex = tabs.length - 1;
        if (nextIndex < 0)
            return;
